  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Establishment types\nenum EstablishmentType {\n  RESTAURANT\n  CAFE\n  CANTEEN\n  COFFEE_SHOP\n  BAKERY\n  FAST_FOOD\n  PUB\n  OTHER\n}\n\n// User roles\nenum Role {\n  ADMIN\n  MANAGER\n  WAITER\n  COOK\n}\n\n// Table statuses\nenum TableStatus {\n  FREE\n  RESERVED\n  OCCUPIED\n}\n\n// Order statuses\nenum OrderStatus {\n  NEW\n  COOKING\n  READY\n  COMPLETED\n  CANCELLED\n}\n\n// Reservation statuses\nenum ReservationStatus {\n  PENDING\n  CONFIRMED\n  CANCELLED\n  COMPLETED\n}\n\n// Payment types\nenum PaymentType {\n  CASH\n  CARD\n  QR\n}\n\n// Establishment (restaurant, cafe, canteen, etc.)\nmodel Establishment {\n  id        String            @id @default(uuid())\n  name      String\n  type      EstablishmentType @default(RESTAURANT)\n  address   String            @default(\"\")\n  phone     String            @default(\"\")\n  createdAt DateTime          @default(now()) @map(\"created_at\")\n  updatedAt DateTime          @updatedAt @map(\"updated_at\")\n\n  users        User[]\n  tables       RestaurantTable[]\n  categories   MenuCategory[]\n  reservations Reservation[]\n\n  @@map(\"establishments\")\n}\n\n// User model with authentication\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  fullName  String   @map(\"full_name\")\n  role      Role     @default(WAITER)\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  establishmentId String?        @map(\"establishment_id\")\n  establishment   Establishment? @relation(fields: [establishmentId], references: [id])\n\n  orders      Order[]\n  reservation Reservation[]\n\n  @@map(\"users\")\n}\n\n// Restaurant tables\nmodel RestaurantTable {\n  id        String      @id @default(uuid())\n  number    Int\n  capacity  Int         @default(4)\n  status    TableStatus @default(FREE)\n  location  String      @default(\"\")\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n\n  establishmentId String        @map(\"establishment_id\")\n  establishment   Establishment @relation(fields: [establishmentId], references: [id])\n\n  orders       Order[]\n  reservations Reservation[]\n\n  @@unique([number, establishmentId])\n  @@map(\"restaurant_tables\")\n}\n\n// Menu categories\nmodel MenuCategory {\n  id          String   @id @default(uuid())\n  name        String\n  description String   @default(\"\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  establishmentId String        @map(\"establishment_id\")\n  establishment   Establishment @relation(fields: [establishmentId], references: [id])\n\n  menuItems MenuItem[]\n\n  @@unique([name, establishmentId])\n  @@map(\"menu_categories\")\n}\n\n// Menu items\nmodel MenuItem {\n  id          String   @id @default(uuid())\n  name        String\n  description String   @default(\"\")\n  price       Float    @default(0)\n  imageUrl    String   @default(\"\") @map(\"image_url\")\n  available   Boolean  @default(true)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  categoryId String?       @map(\"category_id\")\n  category   MenuCategory? @relation(fields: [categoryId], references: [id])\n\n  orderItems OrderItem[]\n\n  @@map(\"menu_items\")\n}\n\n// Customer orders\nmodel Order {\n  id          String       @id @default(uuid())\n  status      OrderStatus  @default(NEW)\n  notes       String       @default(\"\")\n  total       Float        @default(0)\n  paymentType PaymentType? @map(\"payment_type\")\n  paid        Boolean      @default(false)\n  createdAt   DateTime     @default(now()) @map(\"created_at\")\n  updatedAt   DateTime     @updatedAt @map(\"updated_at\")\n\n  tableId String?          @map(\"table_id\")\n  table   RestaurantTable? @relation(fields: [tableId], references: [id])\n\n  waiterId String? @map(\"waiter_id\")\n  waiter   User?   @relation(fields: [waiterId], references: [id])\n\n  items OrderItem[]\n\n  @@map(\"orders\")\n}\n\n// Order items\nmodel OrderItem {\n  id        String   @id @default(uuid())\n  quantity  Int      @default(1)\n  unitPrice Float    @default(0) @map(\"unit_price\")\n  notes     String   @default(\"\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  orderId String @map(\"order_id\")\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  menuItemId String   @map(\"menu_item_id\")\n  menuItem   MenuItem @relation(fields: [menuItemId], references: [id])\n\n  @@map(\"order_items\")\n}\n\n// Table reservations\nmodel Reservation {\n  id            String            @id @default(uuid())\n  customerName  String            @map(\"customer_name\")\n  customerPhone String            @default(\"\") @map(\"customer_phone\")\n  reservedAt    DateTime          @map(\"reserved_at\")\n  partySize     Int               @default(2) @map(\"party_size\")\n  notes         String            @default(\"\")\n  status        ReservationStatus @default(PENDING)\n  createdAt     DateTime          @default(now()) @map(\"created_at\")\n  updatedAt     DateTime          @updatedAt @map(\"updated_at\")\n\n  establishmentId String        @map(\"establishment_id\")\n  establishment   Establishment @relation(fields: [establishmentId], references: [id])\n\n  tableId String?          @map(\"table_id\")\n  table   RestaurantTable? @relation(fields: [tableId], references: [id])\n\n  userId String? @map(\"user_id\")\n  user   User?   @relation(fields: [userId], references: [id])\n\n  @@map(\"reservations\")\n}\n",
